<script setup>
import { router } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AppLayout from '../../Layouts/AppLayout.vue';
import DashboardIcon from '../../components/dashboard/DashboardIcon.vue';
const props=defineProps({month:String,summary:Object,recent:Array,period:Object,links:Object,monthlyTrend:Array,structure:Array,control:Object,topAccounts:Array});
const money=value=>new Intl.NumberFormat('es-NI',{style:'currency',currency:'NIO',maximumFractionDigits:0}).format(Number(value||0));
const statusLabel=value=>({draft:'Borrador',posted:'Contabilizado',reversed:'Reversado'}[value]||value);
const monthLabel=computed(()=>new Intl.DateTimeFormat('es-NI',{month:'long',year:'numeric'}).format(new Date(`${props.month}-01T12:00:00`)));
const isBalanced=computed(()=>Number(props.summary.debit||0)===Number(props.summary.credit||0));
const changeMonth=value=>router.get('/contabilidad',{month:value},{preserveState:true,replace:true});
const executiveOpen=ref(false);
const trendMax=computed(()=>Math.max(...(props.monthlyTrend||[]).map(item=>Number(item.movement)),1));
const structureTotal=computed(()=>(props.structure||[]).reduce((sum,item)=>sum+Math.abs(Number(item.value||0)),0));
const structureGradient=computed(()=>{let cursor=0;const stops=(props.structure||[]).map(item=>{const start=cursor;cursor+=structureTotal.value?Math.abs(Number(item.value))/structureTotal.value*100:0;return `${item.color} ${start}% ${cursor}%`;});return stops.length?`conic-gradient(${stops.join(',')})`:'conic-gradient(#dce6e6 0 100%)';});
const topMax=computed(()=>Math.max(...(props.topAccounts||[]).map(item=>Number(item.movement)),1));
</script>

<template>
<AppLayout title="Centro contable" eyebrow="Control financiero y fiscal" description="Una vista compacta de la operación contable y sus controles.">
 <template #header-actions><a :href="links.createEntry" class="accounting-new"><DashboardIcon name="plus"/> Nuevo asiento</a></template>
 <div class="accounting-center">
  <section class="accounting-overview">
   <div class="accounting-overview-copy">
    <div class="accounting-period-line"><span :data-state="period?.status||'pending'"><i></i>{{period?.status==='closed'?'Período cerrado':period?'Período abierto':'Pendiente de apertura'}}</span><strong>{{monthLabel}}</strong></div>
    <h2>Control contable del período</h2><p>{{period?.status==='closed'?'Los movimientos están protegidos contra cambios retroactivos.':'Registra, revisa y contabiliza los movimientos antes del cierre.'}}</p>
    <div class="accounting-overview-actions"><a :href="links.periods">Gestionar período <span>→</span></a><button type="button" @click="executiveOpen=true">Resumen ejecutivo</button><input :value="month" type="month" aria-label="Cambiar período" @change="changeMonth($event.target.value)"></div>
   </div>
   <div class="accounting-balance" :data-balanced="isBalanced"><span><DashboardIcon :name="isBalanced?'shield':'warning'"/></span><div><small>Control de partida doble</small><strong>{{isBalanced?'Cuadrado':'Revisar diferencia'}}</strong><p>{{summary.posted}} asientos contabilizados</p></div></div>
  </section>
  <section class="accounting-metrics">
   <article v-for="item in [{label:'Debe del período',value:money(summary.debit),caption:'Movimientos contabilizados',icon:'wallet',tone:'blue'},{label:'Haber del período',value:money(summary.credit),caption:'Movimientos contabilizados',icon:'cash',tone:'emerald'},{label:'Pendientes',value:summary.draft,caption:'Asientos en borrador',icon:'warning',tone:'gold'},{label:'Reversiones',value:summary.reversed,caption:'Con asiento compensatorio',icon:'shield',tone:'rose'}]" :key="item.label" class="accounting-metric" :data-tone="item.tone"><span><DashboardIcon :name="item.icon"/></span><div><small>{{item.label}}</small><strong>{{item.value}}</strong><p>{{item.caption}}</p></div></article>
  </section>
  <section class="executive-grid">
   <article class="executive-panel movement-panel"><header><div><span>TENDENCIA CONTABLE</span><h2>Volumen de movimientos</h2></div><a :href="links.journal">Abrir diario →</a></header><div class="movement-chart"><a v-for="item in monthlyTrend" :key="item.label" :href="links.journal" :title="`${item.label}: ${money(item.movement)} · ${item.entries} asientos`"><b>{{money(item.movement)}}</b><i :style="{height:`${Math.max(4,Number(item.movement)/trendMax*100)}%`}"></i><small>{{item.label.split(' ')[0]}}</small></a></div></article>
   <article class="executive-panel structure-panel"><header><div><span>POSICIÓN FINANCIERA</span><h2>Estructura del balance</h2></div><a :href="links.balanceSheet">Ver balance →</a></header><div class="structure-content"><div class="structure-donut" :style="{background:structureGradient}"><span><strong>{{money(structureTotal)}}</strong><small>Base analizada</small></span></div><div><p v-for="item in structure" :key="item.label"><i :style="{background:item.color}"></i><span>{{item.label}}</span><strong>{{money(item.value)}}</strong></p></div></div></article>
   <article class="executive-panel control-panel"><header><div><span>CONTROL INTERNO</span><h2>Preparación del cierre</h2></div><button type="button" @click="executiveOpen=true">Ver diagnóstico</button></header><div class="control-score"><div :style="{'--score':`${control.support_rate}%`}"><strong>{{control.support_rate}}%</strong><small>soporte completo</small></div><ul><li :data-ok="control.drafts===0"><DashboardIcon :name="control.drafts===0?'shield':'warning'"/><span><strong>{{control.drafts}} borradores</strong><small>{{control.drafts===0?'Sin pendientes':'Requieren revisión'}}</small></span></li><li :data-ok="control.missing_support===0"><DashboardIcon :name="control.missing_support===0?'shield':'warning'"/><span><strong>{{control.missing_support}} sin documento</strong><small>Asientos del período</small></span></li></ul></div></article>
   <article class="executive-panel accounts-panel"><header><div><span>ANÁLISIS POR CUENTA</span><h2>Mayor actividad del período</h2></div><a :href="links.ledger">Abrir mayor →</a></header><div class="top-accounts"><p v-for="account in topAccounts" :key="account.id"><span><strong>{{account.code}} · {{account.name}}</strong><small>{{money(account.movement)}}</small></span><i><b :style="{width:`${Math.max(3,Number(account.movement)/topMax*100)}%`}"></b></i></p><p v-if="!topAccounts.length" class="empty-state">Sin movimientos contabilizados.</p></div></article>
  </section>
  <div class="accounting-content">
   <section class="accounting-recent">
    <header><div><span>ACTIVIDAD RECIENTE</span><h2>Últimos movimientos</h2></div><a :href="links.entries">Ver todos →</a></header>
    <div class="accounting-entry-head"><span>Asiento</span><span>Fecha</span><span>Estado</span><span>Monto</span></div>
    <a v-for="entry in recent" :key="entry.id" :href="`/contabilidad/asientos/${entry.id}`" class="accounting-entry"><span class="entry-identity"><i>{{entry.number?.slice(-2)}}</i><span><strong>{{entry.number}}</strong><small>{{entry.concept}}</small></span></span><time>{{entry.date}}</time><em :data-status="entry.status">{{statusLabel(entry.status)}}</em><b>{{money(entry.total_debit)}}</b><span class="entry-arrow">›</span></a>
    <p v-if="!recent.length" class="empty-state">No hay movimientos registrados en este período.</p>
   </section>
  </div>
 </div>
 <div v-if="executiveOpen" class="executive-modal" role="dialog" aria-modal="true" aria-labelledby="executive-title" @click.self="executiveOpen=false"><section><header><div><span>RESUMEN EJECUTIVO</span><h2 id="executive-title">Lectura contable de {{monthLabel}}</h2></div><button type="button" aria-label="Cerrar" @click="executiveOpen=false">×</button></header><div class="modal-result" :data-positive="Number(control.net_result)>=0"><small>Resultado neto acumulado</small><strong>{{money(control.net_result)}}</strong><p>Ingresos {{money(control.income)}} · Gastos {{money(control.expenses)}}</p></div><div class="modal-findings"><article><DashboardIcon :name="isBalanced?'shield':'warning'"/><span><strong>Partida doble {{isBalanced?'cuadrada':'con diferencia'}}</strong><small>Debe {{money(summary.debit)}} · Haber {{money(summary.credit)}}</small></span></article><article><DashboardIcon :name="control.drafts===0?'shield':'warning'"/><span><strong>{{control.drafts===0?'Sin borradores pendientes':`${control.drafts} borradores por revisar`}}</strong><small>Antes de ejecutar el cierre mensual</small></span></article><article><DashboardIcon :name="control.missing_support===0?'shield':'warning'"/><span><strong>{{control.support_rate}}% con soporte documental</strong><small>{{control.missing_support}} movimientos requieren documento</small></span></article></div><footer><a :href="links.incomeStatement">Estado de resultados</a><a :href="links.balanceSheet">Balance general</a><button type="button" @click="executiveOpen=false">Cerrar</button></footer></section></div>
</AppLayout>
</template>

